(128193,	'SKNT-EH-1200FX-ODU-L-1FT',	'80GHz Siklu Full-Duplex FDD 1000Mbit Radio med 30cm antenne',	'EH-1200FX-ODU-L-1FT',	'80ghz-siklu-full-duplex-fdd-1000mbit-radio-med-30cm-antenne',	'eh-1200fx-odu-l-1ft',	'71 - 76GHz FDD-L Radio, 1000Mbps Full-Duplex',	2429042,	'Kontakt os',	'71 - 76GHz FDD-L Radio, 1000Mbps Full-Duplex with 2 x Gbit Ethernet ports. \r\nQoS-aware transparent bridge, adaptive modulation and embedded Web GUI\r\n\r\n\r\n• Professionel trådløs Radio link\r\n• 1000Mbit Fuld-Duplex (2 x 1000Mbit)\r\n• Internet tilslutning til bygninger\r\n• Data link til HD videokameraer\r\n• Backbone link til WiFi og WISP\r\n• Driftsikker Radio link til data, video og voip\r\n• Erstatning eller forlængelse af fibergravning\r\n\r\n• Beslag og Strømforsyning tilkøbes.',	0,	NULL,	'5',	'Outlet',	'Radiolink',	'Siklu',	'sknt-eh-1200fx-odu-l-1ft-2.jpg',	0,	2,	'0',	1,	'OEM',	0,	2082036,	1821782,	1735030,	'',	0,	NULL),
