(127164,	'LW-RAPIDFIRE-5-N',	'4,9 - 6,1GHz LigoPTP RapidFire backhaul, 2 x N-Female',	'RapidFire 5-N',	'4-9-6-1ghz-ligoptp-rapidfire-backhaul-2-x-n-female',	'rapidfire-5-n',	'High-performance Point-to-point bridge with hardware QoS and 600Mbit TDD throughput',	530224,	'Op til 4 hverdage',	'• 2 x N-Female udgang for dual-polarized antenne\r\n• 2 x Gigabit Ethernet porte med PoE-in og PoE-out \r\n• 48 Volt 802.3at PoE  (PoE strømforsyning medfølger) \r\n• W-JET protokol giver den bedste støj-immunitet i sin klasse \r\n• 600Mbit pr. PTP link, hardware QoS, Bandwidth, VLAN, multicast m.m. \r\n• LigoSU klienter administreres centraliseret via LigoPTMP basisstation \r\n• Mere end 7 års holdbarhed med robust hardware, software og overspændingsbeskyttelse',	0,	NULL,	'4',	'Radio Link',	'LigoPTP',	'LigoPTP 5GHz',	'',	0,	2,	'0',	4,	'LigoWave',	0,	424179,	397665,	334039,	'D-3-1-1',	0,	NULL),
