(128186,	'ACC-PSU-48-120W',	'48V Power Adapter 2,5A / 120W',	'PSU-48-120W',	'48v-power-adapter-2-5a-120w',	'psu-48-120w',	'2.1 mm DC jack',	22333,	'Kontakt os',	'48V DC / 2.5A (120W)\r\n2.1 mm DC jack\r\n100 - 240V AC, 50 - 60 Hz \r\nEuropean Type Jack included\r\n\r\nSpecification:\r\nInput Condition : 100 to 240VAC 50/60 Hz 2.0A Max\r\nInput Rated Voltage : 100 to 240VAC\r\nInput Voltage Range : 90 to 264VAC\r\nInput Rated Frequency : 50/60Hz\r\nInput Frequency Range : 47Hz to 63Hz\r\nInput Current : 2.0A Max \r\nInput Inrush Current : 80A Max\r\nInput No Load Power Consumption : 0.5W Max At 115Vac/230Vac\r\nEfficiency : 85% Min\r\nRated Output Power: 120W\r\nOutput Voltage & Current : 48VDC / 2.5A\r\nOutput Load Regulation : ±5%\r\nProtection : OCP OVP SCP OPP\r\nDielectric Withstand Voltage : 3KV 5mA 60s\r\nLeakage Current : 0.25 mA At 230Vac\r\nOperating Temperature: 0 to 40?\r\nStorage Temperature: -10 to 85?\r\nRelative Humidity: 20 to 80%\r\nEuropean Type Jack included',	0,	NULL,	'0,9',	'Tilbehør',	'Strømforsyning',	'Universal',	'acc-psu-48-120w-2.jpg',	0,	2,	'0',	2,	'OEM',	0,	18108,	16750,	15952,	'A-4-1-1',	0,	NULL),
