(127826,	'MT-CCR1009-7G-1C-1S+PC',	'MikroTik Cloud Core Router 1009-7G-1C-1S+PC, passive cooling',	'CCR1009-7G-1C-1S+PC',	'mikrotik-cloud-core-router-1009-7g-1c-1s-pc-passive-cooling',	'ccr1009-7g-1c-1s-pc',	'7 x Gigabit Ethernet, 1 x Combo port (SFP or Gigabit Ethernet), 1 x SFP+ cage, 9 cores x 1GHz CPU, 2GB RAM, LCD panel, passive cooling',	387952,	'Kontakt os',	'<!DOCTYPE HTML PUBLIC &quot;-//W3C//DTD HTML 4.01 Transitional//EN&quot;>\r\n<html><head></head>\r\n<body>Mikrotik RouterOS supports: NAT, DHCP, DNS, VPN, Routing, MPLS, VLAN, Bandwidth management, QoS, Hotspot, Radius and much more.<br><br>&#8226; Mikrotik RouterOS platform:&nbsp;www.mikrotik.com<br>&#8226; Mikrotik hardware&nbsp;specs: www.routerboard.com<br><br><span style=&quot;font-weight: bold;&quot;>For more information, configurations and training, please contact Cloud Router.</span><br></body></html>',	0,	NULL,	'3',	'Switch - Firewall',	'Mikrotik Router',	'Rackmount router',	'mt-ccr1009-7g-1c-1s+pc-2.jpg',	0,	2,	'0',	0,	'Mikrotik',	0,	316487,	293329,	286345,	'C-2-3-2',	0,	NULL),
(127534,	'MN-B5C',	'5GHz Mimosa B5c 1Gbps+ carrier grade AP bridge med 2 x N-hun',	'B5c',	'5ghz-mimosa-b5c-1gbps-carrier-grade-ap-bridge-med-2-x-n-hun',	'b5c',	'Benyttes som bridge AP eller klient til Point-to-point, med en ekstern MIMO panel antenne',	311760,	'Kontakt os',	'Product Specifications:\r\n • Max throughput: Up to 1.5Gbps IP aggregate UL/DL (1.7Gbps PHY)\r\n • Low latency: 2+ ms\r\n • Wireless protocols: TDMA, TDMA-FD\r\n • MiMO & Modulation: 4x4:4 MiMO OFDM up to 256QAM\r\n • Bandwidth: Single or dual 20/40/80 MHz channels\r\n • Frequency range: 4900-6000MHz (country restrictions may apply) (*new* US/FCC 5600-5650 support)\r\n • Max output power: 30dBm (2-stream), 27dBm (4-stream)\r\n • Max power consumption: 20W\r\n • Power method: 48VDC, 802.3at PoE\r\n • ESD Protection: 6kV\r\n • Connector type: 2 x female type N\r\n • Operating Temperature: -40deg C to +55deg C (-40deg F to 131deg F)\r\n • Security: 128-bit AES PSK with hardware\r\n • QoS: Supports 4 pre-configured QoS levels\r\n • Approvals: FCC part 15.407, IC RS10, CE, ETSI 301 893/302 502\r\n • RoHS compliance: Yes\r\n • Safety: UL/EC/EN/ 60950-1 + CSA-22.2\r\n\r\nProduct Features:\r\n • Massive bandwidth\r\n • Customization\r\n • Outdoor UV stabilized plastic\r\n • Weatherproof IP67 rating\r\n • Gigabit Ethernet: 10/100/1000-BASE-T\r\n • Wind durability up to 200 km/h (125 mph)\r\n • Hands-free dedicated 2.4 GHz Wi-Fi management radio\r\n • Smart spectrum management \r\n • Active scan monitors/logs ongoing RF interference across channels (no service impact)\r\n • Dynamic auto-optimization of channel and bandwidth use\r\n\r\nProduct Includes:\r\n • B5c radio\r\n • Pole mounting kit\r\n • Gigabit PoE injector',	0,	NULL,	'3',	'Outlet',	'Radiolink',	'Mimosa Networks',	'mn-b5c-2.jpg',	0,	2,	'0',	1,	'OEM',	0,	271790,	258532,	246508,	'B-3-2-1',	0,	NULL),
