(127375,	'MT-RB260GSP',	'MikroTik RouterBoard 260GSP, Passive PoE switch',	'RB260GSP',	'mikrotik-routerboard-260gsp-passive-poe-switch',	'rb260gsp',	'1 x SFT, 4 x PoE Ethernet ports, passive PoE out, same as DC power or PoE-in at port 1, Mikrotik SwOS',	44306,	'Kontakt os',	'<!DOCTYPE HTML PUBLIC &quot;-//W3C//DTD HTML 4.01 Transitional//EN&quot;>\r\n<html><head></head>\r\n<body>Mikrotik RouterOS supports: NAT, DHCP, DNS, VPN, Routing, MPLS, VLAN, Bandwidth management, QoS, Hotspot, Radius and much more.<br><br>&#8226; Mikrotik RouterOS platform:&nbsp;www.mikrotik.com<br>&#8226; Mikrotik hardware&nbsp;specs: www.routerboard.com<br><br><span style=&quot;font-weight: bold;&quot;>For more information, configurations and training, please contact Cloud Router.</span><br></body></html>',	0,	NULL,	'2',	'Switch - Firewall',	'Mikrotik Switch',	'Desktop',	'mt-rb260gsp-2.jpg',	0,	2,	'0',	0,	'Mikrotik',	0,	36145,	33500,	32702,	'C-2-2-1',	0,	NULL),
