(127346,	'ANT-AP-8070',	'14dBi 2GHz panel antenna for 3G, N-female',	'AP-8070',	'14dbi-2ghz-panel-antenna-for-3g-n-female',	'ap-8070',	'1900MHz - 2140MHz panel antenna for 3G',	43400,	'Kontakt os',	'Frekvenser i Danmark\r\n• 800 MHz: Band 20 (4G, Telia-Telenor og TDC)\r\n• 900 MHz: Band 8 (3G og 2G, alle netværk)\r\n• 1800 MHz: Band 3 (4G, Telia-Telenor og 3, 2G, alle netværk)\r\n• 2100 MHz: Band 1 (3G, alle netværk)\r\n• 2600 MHz: Band 7 (4G, alle netværk)',	0,	NULL,	'2',	'Outlet',	'Antenne',	'Directional',	'ant-ap-8070-2.jpg',	0,	2,	'0',	7,	'OEM',	0,	35189,	32550,	31000,	'G-3-2-2',	0,	NULL),
(127348,	'WL-R210LH1-D',	'LTE Industriel DIN-rail Internet Gateway 3G/4G, Dual-SIM, WiFi',	'R210LH1-D',	'lte-industriel-din-rail-internet-gateway-3g-4g-dual-sim-wifi',	'r210lh1-d',	'Anbefalet til maskiner og køretøjer, understøtter internet, VPN, VLAN og Serial tilslutning over 3G/4G netværk',	275028,	'Kontakt os',	'• Industrial robust design and Din-rail metal housing \r\n• High data speed via LTE 4G network, 3G, 2.5G backword compatible\r\n• Strong electromagnetic interference Resistance, heat endurance and radiation ability\r\n• Ultra security, VPN: PPTP, L2TP, GPE, IPSec VPN (optional)\r\n• Built-in watch dog, Multi-link detection\r\n• 802.11b/g/n Wi-Fi support, 150Mbps data rate\r\n• MIMO Antenna for 4G\r\n• 2 x LAN or 1xLAN, 1xWAN, 3 x I/O and 1 x RS232\r\n• WAN port support PPPoE, static IP, DHCP client.\r\n• Always online, reboot automatically if disconnected to ensure continual connection\r\n• Support APN and VPDN wireless private network access in\r\n• LCP/ICMP/flow/heartbeat check, ensure network usability\r\n• Web/CLI/SSH/Management platform support, easy configure\r\n• SNMP network management, NTP support\r\n• Local & remote management (configuration, status, upgrade firmware)\r\n• Supports DHCP Server\r\n• Supports DNS proxy and Dynamic DNS (DDNS)\r\n• Supports timing operation\r\n• Supports LED status indication\r\n• Shock and vibration resistant\r\n\r\n• Applications \r\n• ATM/Vending Machine Connectivity \r\n• Solar/Wind Energy Monitor \r\n• Distribution Automation \r\n• Automatic Meter Reading \r\n• Industrial Automation \r\n• IP Video Surveillance \r\n• Remote Devices\r\n\r\n\r\nOm WLINK\r\nWLINK er en Shenzhen og Hong Kong baseret mobil data kommunikation specialist med fokus på M2M og IoT løsninger til industriel og transportsektor.',	0,	NULL,	'1',	'Outlet',	'WiFi',	'LTE',	'wl-r210lh1-d-2.jpg',	0,	2,	'0',	1,	'OEM',	0,	229190,	211560,	201240,	'3-5-4',	0,	NULL),
