(127273,	'YDELSER-10KLIPS',	'10stk. af 15 minutters klippekort til remote teknisk assistance',	'SUPPORT-10KLIP',	'10stk-af-15-minutters-klippekort-til-remote-teknisk-assistance',	'support-10klip',	'2,5 timer fordelt over 10 supportklip, SLA to timer',	159400,	'Levering via e-mail',	'Fordele\r\n• Besparelser i timepriser\r\n• Hurtig adgang til assistance uden akutgebyr (inden for to timer)\r\n\r\n\r\nRådgivning\r\nRådgivning med fokus på praktiske strategier og løsninger, som kommer Jeres virksomhed til gode ved design og implementering af datakommunikation.\r\n\r\n\r\nTeknisk assistance \r\nTeknisk assistance dækker alt lige fra opsætning af udstyr, til ændringer af konfigurationer og fejlfinding.\r\n\r\n\r\nHåndtering\r\n• Servicesag oprettes via vores Online-formular, telefon eller support e-mail service@cloudrouter.dk\r\n• Sagens forløb opdateres løbende til kontaktpersonen via e-mail.',	0,	NULL,	'0',	'Tilbehør',	'Ydelser',	'Klippekort',	'ydelser-10klips-2.jpg',	0,	2,	'0',	0,	'CloudRouter',	0,	127520,	127520,	127520,	'',	0,	NULL),
