(128191,	'SKNT-EH-1200TL-ODU-1FT',	'70GHz Siklu EtherHaul TDD 700Mbit Radio med 30cm antenne',	'EH-1200TL-ODU-1FT',	'70ghz-siklu-etherhaul-tdd-700mbit-radio-med-30cm-antenne',	'eh-1200tl-odu-1ft',	'71 - 76GHz TDD Radio med 30cm antenne. 700Mbps TDD throughput.',	1263745,	'Kontakt os',	'71 - 76GHz TDD Radio, 700Mbps TDD throughput with 2 x Gbit Ethernet and 2 x Fiber ports, \r\nQoS-aware transparent bridge, adaptive modulation and embedded Web GUI.\r\n\r\n\r\n• Professionel trådløs TDD Radio link 700Mbit throughput \r\n• Internet tilslutning til bygninger \r\n• Data link til HD videokameraer \r\n• Backbone link til WiFi og WISP \r\n• Driftsikker Radio link til data, video og voip \r\n• Erstatning eller forlængelse af fibergravning \r\n\r\n• 71 - 76GHz TDD Radio with 30cm Antenna. \r\n• 700Mbps aggregated throughput with 2 combo ports: 2 x Copper, 2 x Fiber\r\n• Beslag og Strømforsyning tilkøbes',	0,	NULL,	'5',	'Outlet',	'Radiolink',	'Siklu',	'',	0,	2,	'0',	1,	'OEM',	0,	1083210,	947809,	902675,	'',	0,	NULL),
